local Window = getgenv().SORU_Window
if not Window then return end

local Players = game:GetService("Players")
local TweenService = game:GetService("TweenService")
local LP = Players.LocalPlayer

getgenv().AntiGuard = false
getgenv().AutoSteal = false
getgenv().SelectedArea = nil
getgenv().TweenSpeed = 25
getgenv().StealMode = "Normal"
getgenv().AutoTreadmill = false

local TARGET_DIST = 1000
local OTHER_DIST = 0
local BlockedBases,BossRF={},nil
pcall(function() BossRF = game.ReplicatedStorage.Packages._Index["sleitnick_knit@1.7.0"].knit.Services.AreaService.RF:WaitForChild("BossCaught") end)
local function RefreshBases() table.clear(BlockedBases) local f=workspace:FindFirstChild("SpawnedBases") if f then for _,m in ipairs(f:GetChildren()) do BlockedBases[m.Name]=true end end end
RefreshBases()
local oldNamecall oldNamecall=hookmetamethod(game,"__namecall",newcclosure(function(self,...) if getgenv().AntiGuard and not checkcaller() and getnamecallmethod()=="InvokeServer" then if self.Name=="BossCaught" or self==BossRF then local id=... if typeof(id)=="string" and (BlockedBases[id] or id:match("^base_")) then return nil end end end return oldNamecall(self,...) end))

local SavedPromptDist={}
local function isGamepassPrompt(p) local f=(p:GetFullName().." "..p.Name.." "..(p.ObjectText or "").." "..(p.ActionText or "")):lower() return f:find("gamepass") or f:find("robux") end
local function restorePrompts() for pr,old in pairs(SavedPromptDist) do if pr and pr.Parent then pcall(function() pr.MaxActivationDistance=old end) end end table.clear(SavedPromptDist) end
local function hackPrompts(validHens) for _,o in ipairs(workspace:GetDescendants()) do if o:IsA("ProximityPrompt") then if SavedPromptDist[o]==nil then SavedPromptDist[o]=o.MaxActivationDistance end if isGamepassPrompt(o) then pcall(function() o.MaxActivationDistance=0 end) else local isT=false for _,hen in ipairs(validHens) do if o:IsDescendantOf(hen) then isT=true break end end pcall(function() o.MaxActivationDistance=isT and TARGET_DIST or OTHER_DIST end) end end end end
local function tweenTo(cf) local hrp=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") if not hrp then return end local dist=(hrp.Position-cf.Position).Magnitude local dur=math.clamp(dist / getgenv().TweenSpeed, 0.1, 20) local tw=TweenService:Create(hrp,TweenInfo.new(dur,Enum.EasingStyle.Linear),{CFrame=cf}) tw:Play() local done=false tw.Completed:Connect(function() done=true end) repeat task.wait() until done or not getgenv().AutoSteal and not getgenv().SingleSteal end
local function getPos(obj) local ok,cf=pcall(function() return obj:GetPivot() end) if ok then return cf.Position end if obj:IsA("BasePart") then return obj.Position end local bp=obj:FindFirstChildWhichIsA("BasePart",true) return bp and bp.Position or nil end
local function getEggModel(hen) for _,d in ipairs(hen:GetDescendants()) do if d.Name:lower():find("egg") then return d end end return nil end
local function hasEggChild(hen) return getEggModel(hen)~=nil end
local function safeInteractHen(hen) for _,o in ipairs(hen:GetDescendants()) do if o:IsA("ProximityPrompt") and not isGamepassPrompt(o) then pcall(function() fireproximityprompt(o,0) end) end end end
local function getAreaPart(n) local a=workspace:FindFirstChild("Areas") return a and a:FindFirstChild(n) or nil end
local function getClosestBase(areaObj) local aPos=getPos(areaObj) if not aPos then return nil end local closest,minD=nil,math.huge local spawned=workspace:FindFirstChild("SpawnedBases") if not spawned then return nil end for _,base in ipairs(spawned:GetChildren()) do local bPos=getPos(base) if not bPos then continue end local has=false for _,c in ipairs(base:GetChildren()) do if c.Name:match("^Hen_") and hasEggChild(c) then has=true break end end if not has then continue end local d=(bPos-aPos).Magnitude if d<minD then minD=d closest=base end end return closest end
local function getValidHens(base) local t={} for _,v in ipairs(base:GetChildren()) do if v.Name:match("^Hen_") and hasEggChild(v) then table.insert(t,v) end end return t end

local fakeClone,savedTrans=nil,{}
local savedCamCF, savedCamType, savedCamSubj
local cam = workspace.CurrentCamera
local function lockCamera() savedCamCF = cam.CFrame savedCamType = cam.CameraType savedCamSubj = cam.CameraSubject cam.CameraType = Enum.CameraType.Scriptable cam.CFrame = savedCamCF end
local function unlockCamera() if savedCamType then cam.CameraType = savedCamType end if savedCamSubj then cam.CameraSubject = savedCamSubj end end
local function createFakeClone(atCF) local char=LP.Character if not char then return end char.Archivable=true local clone=char:Clone() clone.Name="FakeClone_"..LP.Name for _,o in ipairs(clone:GetDescendants()) do if o:IsA("LocalScript") or o:IsA("Script") then o:Destroy() elseif o:IsA("BasePart") then o.Anchored=true o.CanCollide=false end end clone.Parent=workspace pcall(function() clone:SetPrimaryPartCFrame(atCF) end) return clone end
local function setInvisible(v) local char=LP.Character if not char then return end if v then table.clear(savedTrans) for _,p in ipairs(char:GetDescendants()) do if p:IsA("BasePart") then savedTrans[p]=p.Transparency p.Transparency=1 end end else for o,t in pairs(savedTrans) do if o and o.Parent then pcall(function() o.Transparency=t end) end end table.clear(savedTrans) end end

local doStealLoop, refreshPanelCards, getPanelContent, doTreadmillLoop
local function getWalkSpeed() local hum = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") return hum and math.floor(hum.WalkSpeed) or 16 end

-- TAB GUARD
local GuardTab = Window:Tab({Title="Guard", Icon="G"})
local GuardAcc = GuardTab:Accordion({Title="Anti Guard", Open=true})
GuardAcc:Toggle({Title="Enable Anti Guard", Flag="AntiGuardFlag", Default=false, Callback=function(v) getgenv().AntiGuard=v RefreshBases() end})

-- TAB EGG
local EggTab = Window:Tab({Title="Egg", Icon="E"})
local EggAcc = EggTab:Accordion({Title="Auto Steal", Open=true})
local areasList={} pcall(function() for _,v in ipairs(workspace.Areas:GetChildren()) do table.insert(areasList,v.Name) end end) if #areasList==0 then areasList={"No Areas Found"} end
getgenv().SelectedArea=areasList[1]
EggAcc:Dropdown({Title="Select Area", Flag="AreaDropdown", Options=areasList, Default=areasList[1], Callback=function(v) getgenv().SelectedArea=v end})
EggAcc:Dropdown({Title="Mode", Flag="ModeFlag", Options={"Normal","Silent"}, Default="Normal", Callback=function(v) getgenv().StealMode=v end})
EggAcc:Slider({Title="WalkSpeed: "..getWalkSpeed().." (asli) | TweenSpeed", Desc="WalkSpeed asli: "..getWalkSpeed(), Flag="TweenSpeedFlag", Min=10, Max=500, Step=5, Default=25, Callback=function(v) getgenv().TweenSpeed=v end})
EggAcc:Slider({Title="WalkSpeed: "..getWalkSpeed(), Flag="WalkSpeedFlag", Min=16, Max=100, Step=1, Default=getWalkSpeed(), Callback=function(v) local hum=LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if hum then hum.WalkSpeed=v end end})

-- TAB TREADMILL BARU
local TreadTab = Window:Tab({Title="Treadmill", Icon="T"})
local TreadAcc = TreadTab:Accordion({Title="Auto Treadmill", Open=true})
doTreadmillLoop = function()
    task.spawn(function()
        while getgenv().AutoTreadmill do
            pcall(function() game.ReplicatedStorage.Packages._Index["sleitnick_knit@1.7.0"].knit.Services.TrainingService.RF.StartTraining:InvokeServer() end)
            task.wait(0.5)
        end
    end)
end
TreadAcc:Toggle({Title="Auto Treadmill", Flag="AutoTreadFlag", Default=false, Callback=function(v) getgenv().AutoTreadmill=v if v then doTreadmillLoop() end end})

-- PANEL (O) - Pake Window:Panel bawaan loader, GripY bisa ditarik
local Panel = Window:Panel({
    Title = "Egg Panel",
    Subtitle = "WalkSpeed: "..getWalkSpeed().." | Kiri gambar | Tengah nama | Kanan steal",
    Width = 360, Height = 520,
    MinWidth = 300, MaxWidth = 500,
    Resizable = true,
    OpenDrag = "Left",
    GripY = 0.5,
    Open = false
})

getPanelContent = function()
    for _,gui in ipairs({game.CoreGui, LP.PlayerGui}) do
        local holder = gui:FindFirstChild("SORU_Panel", true)
        if holder then
            local c = holder:FindFirstChild("Content", true)
            if c and c:IsA("ScrollingFrame") then return c, holder end
        end
    end
    return nil
end

local function createCardBase(parent, h, name)
    local _, holder = getPanelContent()
    local cardColor = Color3.fromRGB(42,42,48)
    if holder then
        local body = holder:FindFirstChild("Card", true) and holder:FindFirstChild("Card", true):FindFirstChild("Body")
        if body then cardColor = Color3.fromRGB(math.clamp(body.BackgroundColor3.R*255+10,0,255), math.clamp(body.BackgroundColor3.G*255+10,0,255), math.clamp(body.BackgroundColor3.B*255+10,0,255)) end
    end
    local card = Instance.new("Frame")
    card.Name = name
    card.Size = UDim2.new(1, -4, 0, h)
    card.BackgroundColor3 = cardColor
    card.BorderSizePixel = 0
    card.Parent = parent
    Instance.new("UICorner", card).CornerRadius = UDim.new(0,12)
    local st = Instance.new("UIStroke") st.Color = Color3.fromRGB(255,255,255) st.Transparency = 0.85 st.Thickness = 1 st.Parent = card
    return card
end

local function createEggCardUI(parentContent, hen)
    local eggObj = getEggModel(hen)
    local eggName = hen.Name.." | "..(eggObj and eggObj.Name or "Egg")
    local card = createCardBase(parentContent, 72, "EggCard_"..hen.Name)
    local vp = Instance.new("ViewportFrame")
    vp.Size = UDim2.new(0,60,0,60) vp.Position = UDim2.new(0,6,0,6) vp.BackgroundColor3 = Color3.fromRGB(20,20,25) vp.BorderSizePixel = 0 vp.Parent = card
    Instance.new("UICorner", vp).CornerRadius = UDim.new(0,8)
    local lbl = Instance.new("TextLabel") lbl.Size = UDim2.new(1, -140, 1, 0) lbl.Position = UDim2.new(0,72,0,0) lbl.BackgroundTransparency = 1 lbl.Text = eggName lbl.TextColor3 = Color3.fromRGB(230,230,230) lbl.Font = Enum.Font.GothamBold lbl.TextSize = 11 lbl.TextXAlignment = Enum.TextXAlignment.Left lbl.TextWrapped = true lbl.Parent = card
    local btn = Instance.new("TextButton") btn.Size = UDim2.new(0,58,0,32) btn.Position = UDim2.new(1, -64, 0.5, -16) btn.Text = "Steal" btn.BackgroundColor3 = Color3.fromRGB(74,222,128) btn.TextColor3 = Color3.fromRGB(0,0,0) btn.Font = Enum.Font.GothamBold btn.TextSize = 12 btn.Parent = card Instance.new("UICorner", btn).CornerRadius = UDim.new(0,8)
    if eggObj then
        local cam = Instance.new("Camera") vp.CurrentCamera = cam cam.Parent = vp
        pcall(function() local clone = eggObj:Clone() if clone:IsA("BasePart") then local m=Instance.new("Model") clone.Parent=m clone=m end clone.Parent=vp local cf,size=clone:GetBoundingBox() cam.CFrame=CFrame.new(cf.Position+Vector3.new(0,0,size.Magnitude*1.2), cf.Position) end)
    end
    btn.MouseButton1Click:Connect(function()
        if getgenv().SingleSteal then return end
        getgenv().SingleSteal=true
        task.spawn(function()
            local hrp=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") if not hrp then getgenv().SingleSteal=false return end
            local oldCF=hrp.CFrame hackPrompts({hen})
            local isSilent=getgenv().StealMode=="Silent" local fClone if isSilent then lockCamera() fClone=createFakeClone(oldCF) setInvisible(true) end
            local henPos=getPos(hen) if henPos then tweenTo(CFrame.new(henPos+Vector3.new(0,5,0))) end
            local t=tick() repeat safeInteractHen(hen) task.wait(0.05) until tick()-t>=0.5
            tweenTo(oldCF)
            if isSilent then setInvisible(false) unlockCamera() if fClone then pcall(function() fClone:Destroy() end) end end
            restorePrompts() -- balikin interact
            getgenv().SingleSteal=false
        end)
    end)
end

refreshPanelCards = function()
    local content = getPanelContent() if not content then return end
    for _,ch in ipairs(content:GetChildren()) do if ch.Name:find("EggCard_") then ch:Destroy() end end
    local areaObj=getAreaPart(getgenv().SelectedArea) if not areaObj then return end
    local base=getClosestBase(areaObj) if not base then return end
    local hens=getValidHens(base)
    for _,hen in ipairs(hens) do createEggCardUI(content, hen) end
end

doStealLoop = function()
    task.spawn(function()
        while getgenv().AutoSteal do
            RefreshBases()
            local areaObj=getAreaPart(getgenv().SelectedArea) if not areaObj then task.wait(1) continue end
            local base=getClosestBase(areaObj) if not base then task.wait(1) continue end
            local hens=getValidHens(base) if #hens==0 then task.wait(1) continue end
            hackPrompts(hens)
            local hrp=LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") if not hrp then task.wait(1) continue end
            local oldCF=hrp.CFrame local basePos=getPos(base) if not basePos then task.wait(1) continue end
            local isSilent=getgenv().StealMode=="Silent" local fClone if isSilent then lockCamera() fClone=createFakeClone(oldCF) setInvisible(true) end
            tweenTo(CFrame.new(basePos+Vector3.new(0,5,0)))
            if not getgenv().AutoSteal then break end
            local t=tick() repeat for _,hen in ipairs(hens) do safeInteractHen(hen) end task.wait(0.05) until tick()-t>=0.5 or not getgenv().AutoSteal
            tweenTo(oldCF)
            if isSilent then setInvisible(false) unlockCamera() if fClone then pcall(function() fClone:Destroy() end) end end
            task.wait(0.5)
        end
        restorePrompts() setInvisible(false) unlockCamera() if fakeClone then pcall(function() fakeClone:Destroy() end) fakeClone=nil end
    end)
end

EggAcc:Toggle({Title="Auto Steal", Flag="AutoStealFlag", Default=false, Callback=function(v) getgenv().AutoSteal=v if v and getgenv().SelectedArea~="No Areas Found" then doStealLoop() else restorePrompts() setInvisible(false) unlockCamera() if fakeClone then pcall(function() fakeClone:Destroy() end) fakeClone=nil end end end})
LP.CharacterAdded:Connect(function(char) char:WaitForChild("Humanoid").WalkSpeed = getWalkSpeed() end)
task.spawn(function() while true do pcall(refreshPanelCards) task.wait(2.5) end end)
